import type { MedusaContainer } from "@medusajs/framework/types"
import { ContainerRegistrationKeys, Modules } from "@medusajs/framework/utils"
import { likeLiteral } from "../../lib/db/like"
import { errorSummary, logger } from "../../lib/logging"

type Container = Pick<MedusaContainer, "resolve">

/**
 * What Medusa's auth service lists beyond its published types (2.21.2,
 * generated by MedusaService): operators and JSON filters on its rows.
 */
interface AuthRows {
  listProviderIdentities: (
    filters: Record<string, unknown>,
    config: { select: string[]; take: null }
  ) => Promise<{ auth_identity_id?: string | null }[]>
  listAuthIdentities: (
    filters: { id: string[] },
    config: { select: string[]; take: null }
  ) => Promise<{ id: string; app_metadata?: Record<string, unknown> | null }[]>
  listAuthVerifications: (
    filters: Record<string, unknown>,
    config: { select: string[]; take: null }
  ) => Promise<{ verified_at: Date | string | null }[]>
}

const ids = (rows: { auth_identity_id?: string | null }[]) =>
  rows.flatMap((row) => (row.auth_identity_id ? [row.auth_identity_id] : []))

/** The sign-ins of this customer among these identities (app_metadata.customer_id). */
async function ownIdentities(auth: AuthRows, candidates: string[], customerId: string) {
  if (candidates.length === 0) {
    return []
  }
  const identities = await auth.listAuthIdentities(
    { id: [...new Set(candidates)] },
    { select: ["id", "app_metadata"], take: null }
  )
  return identities
    .filter((identity) => identity.app_metadata?.["customer_id"] === customerId)
    .map((identity) => identity.id)
}

/**
 * A social sign-in of the customer whose provider vouched for the address
 * (`loginEmailOf`'s rule: Google refuses an unverified one). Read with a
 * JSON filter; a failure counts as no proof.
 */
async function vouchedBySocial(auth: AuthRows, email: string, customerId: string) {
  try {
    const rows = await auth.listProviderIdentities(
      { provider: { $ne: "emailpass" }, user_metadata: { email } },
      { select: ["auth_identity_id"], take: null }
    )
    return (await ownIdentities(auth, ids(rows), customerId)).length > 0
  } catch (error) {
    logger.warn({ event: "account.social_proof_unread", err: errorSummary(error) })
    return false
  }
}

/**
 * Whether the customer has proven they own their address (security review
 * of ADR-0068 slice 1b, H1): `has_account` alone is not proof, since an
 * e-mail registration has it before its address is confirmed. Proven is:
 * an e-mail sign-in of this customer whose own address was confirmed with
 * the mailed code in that sign-in's session (an `AuthVerification` of
 * that identity for that address, verified), or a social sign-in of this
 * customer whose provider vouched for the address. A code asked for
 * another address, or by another identity, proves nothing.
 */
export async function provenCustomer(container: Container, customerId: string): Promise<boolean> {
  const { data } = await container.resolve(ContainerRegistrationKeys.QUERY).graph({
    entity: "customer",
    fields: ["id", "email", "has_account"],
    filters: { id: customerId },
  })
  const customer = data[0] as { email?: string | null; has_account?: boolean } | undefined
  const email = (customer?.email ?? "").trim().toLowerCase()
  if (!customer?.has_account || email === "") {
    return false
  }
  const auth = container.resolve(Modules.AUTH) as unknown as AuthRows
  const address = { $ilike: likeLiteral(email) }
  const logins = await auth.listProviderIdentities(
    { provider: "emailpass", entity_id: address },
    { select: ["auth_identity_id"], take: null }
  )
  const own = await ownIdentities(auth, ids(logins), customerId)
  if (own.length > 0) {
    const confirmations = await auth.listAuthVerifications(
      { entity_type: "email", entity_id: address, auth_identity_id: own },
      { select: ["verified_at"], take: null }
    )
    if (confirmations.some(({ verified_at: verifiedAt }) => verifiedAt !== null)) {
      return true
    }
  }
  return vouchedBySocial(auth, email, customerId)
}
